// Canonical GSAP "animate to height: auto" pattern
// (WebFetch was blocked by Cloudflare on both demos.gsap.com and codepen.io;
//  this is the well-established recipe Jack Doyle/GreenSock recommends.)

import { gsap } from "gsap";

// One-shot open: 0 -> auto
function openPanel(el) {
  gsap.set(el, { height: 0, overflow: "hidden", display: "block" });
  gsap.to(el, {
    height: el.scrollHeight, // measured pixel target
    duration: 0.5,
    ease: "power2.inOut",
    onComplete: () => {
      // Release the lock so the panel reflows naturally afterward.
      gsap.set(el, { height: "auto", overflow: "" });
    },
  });
}

// Reusable open/close helper (re-measures every time, handles re-entrance)
function animateHeight(el, open, { duration = 0.5, ease = "power2.inOut" } = {}) {
  // Kill any in-flight tween so we don't fight it
  gsap.killTweensOf(el);

  if (open) {
    // Snapshot current height, force auto to measure target, then tween back
    const start = el.getBoundingClientRect().height;
    gsap.set(el, { height: "auto", overflow: "hidden" });
    const end = el.getBoundingClientRect().height;
    gsap.fromTo(
      el,
      { height: start },
      {
        height: end,
        duration,
        ease,
        onComplete: () => gsap.set(el, { height: "auto" }),
      }
    );
  } else {
    const start = el.getBoundingClientRect().height;
    gsap.fromTo(
      el,
      { height: start },
      { height: 0, overflow: "hidden", duration, ease }
    );
  }
}

